@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#f4f3f8;--muted:#a9a8b8;--dim:#77798e;--cyan:#6ee7e4;--violet:#a88bff;--gold:#ffcf80;--panel:rgba(12,15,29,.82);--line:rgba(206,220,255,.16)}*{box-sizing:border-box}html,body{height:100%;margin:0;overflow:hidden;background:#090c18;color:var(--ink);font-family:'DM Sans',sans-serif;user-select:none;-webkit-user-select:none;touch-action:none}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100dvh;overflow:hidden;background:#111426}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(5,8,19,.58),transparent 25%,transparent 60%,rgba(5,8,19,.55)),radial-gradient(ellipse at center,transparent 35%,rgba(4,6,15,.36) 100%)}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:78px;display:flex;align-items:center;padding:0 34px;border-bottom:1px solid rgba(220,229,255,.1);background:linear-gradient(180deg,rgba(7,10,23,.72),rgba(7,10,23,.06))}.brand{display:flex;align-items:center;gap:12px}.brand-mark{width:37px;height:37px;border:1px solid rgba(110,231,228,.6);display:grid;place-items:center;color:var(--cyan);font-size:20px;transform:rotate(45deg);text-shadow:0 0 15px var(--cyan)}.brand-mark::first-letter{transform:rotate(-45deg)}.brand-name{font:700 13px 'Space Grotesk';letter-spacing:2.1px}.brand-name span{color:var(--cyan)}.brand-kicker{font:500 8px 'DM Sans';letter-spacing:2px;color:#9298aa;margin-top:3px}.realm-chip{position:absolute;left:50%;transform:translateX(-50%);display:flex;gap:10px;align-items:center;font:600 10px 'Space Grotesk';letter-spacing:1.55px;color:#eeeff6}.realm-dot{width:6px;height:6px;background:#74e9d8;box-shadow:0 0 10px #74e9d8;border-radius:50%}.realm-divider{color:#62677a}.realm-chip #weather-name{color:#a7a9bb}.icon-button{margin-left:auto;background:rgba(17,22,40,.52);border:1px solid var(--line);width:38px;height:38px;color:var(--cyan);font-size:22px;border-radius:2px;cursor:pointer}.hud-left{position:absolute;z-index:2;top:102px;left:34px;width:255px}.player-card{display:flex;align-items:center;gap:11px;padding-bottom:15px;border-bottom:1px solid var(--line)}.avatar{width:39px;height:39px;display:grid;place-items:center;background:linear-gradient(145deg,#172e45,#32264c);border:1px solid rgba(110,231,228,.45);color:#afffff;font:20px serif;box-shadow:0 0 20px rgba(100,233,220,.15)}.player-info{flex:1}.player-name{font:700 11px 'Space Grotesk';letter-spacing:1.4px}.level{display:inline-block;margin-left:5px;color:#f8d08b;border:1px solid rgba(255,207,128,.45);padding:1px 4px;font-size:8px}.player-sub{font-size:8px;letter-spacing:1.6px;color:#9e9eb1;margin-top:4px}.dots{border:0;background:none;color:#a6a8bb;letter-spacing:2px;font-size:12px;cursor:pointer}.vital{margin-top:14px}.vital-head{display:flex;justify-content:space-between;font:600 8px 'Space Grotesk';letter-spacing:1.4px;color:#bbbccc}.vital-head span:last-child{color:#e2e4ef;letter-spacing:.5px}.bar{height:4px;margin-top:6px;background:rgba(223,226,240,.12);overflow:hidden}.bar i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#ff617b,#ff9a8a);box-shadow:0 0 8px #f2758d;transition:width .2s}.energy-vital{margin-top:10px}.energy-vital .bar i{background:linear-gradient(90deg,#658eff,#b894ff);box-shadow:0 0 8px #9d8eff}.awakening-card{margin-top:17px;padding:10px 11px;display:flex;align-items:center;gap:9px;background:rgba(14,19,37,.62);border:1px solid rgba(171,151,255,.22)}.awaken-icon{font-size:21px;color:#c5aaff;text-shadow:0 0 14px #b49aff}.tiny-label{font:600 8px 'Space Grotesk';letter-spacing:1.45px;color:#a5a7b8}.awaken-name{font:700 10px 'Space Grotesk';letter-spacing:1.2px;margin-top:3px}.path-progress{margin-top:6px;height:2px;width:138px;background:#292943}.path-progress i{height:100%;display:block;width:0;background:linear-gradient(90deg,#8a72f9,#73eddf);transition:width .4s}.path-percent{margin-left:auto;color:#bec1d3;font-size:9px}.objective-card{position:absolute;z-index:2;right:34px;top:103px;width:278px;padding:14px 15px;background:linear-gradient(135deg,rgba(13,17,34,.86),rgba(18,21,38,.68));border:1px solid rgba(193,199,225,.18);box-shadow:0 12px 40px rgba(0,0,0,.14)}.objective-top{display:flex;align-items:center;gap:7px}.quest-icon{font-size:16px;color:var(--gold)}.objective-pin{margin-left:auto;color:#83e5dc;font-size:13px}.objective-title{font:700 13px 'Space Grotesk';letter-spacing:1.2px;margin:9px 0 5px}.objective-copy{color:#aaadbe;font-size:10px;line-height:1.55}.objective-step{display:flex;align-items:flex-start;gap:8px;margin-top:12px;padding:8px;background:rgba(112,134,193,.1);font-size:9px;line-height:1.35;color:#e3e3ed}.step-dot{margin-top:2px;flex:none;width:6px;height:6px;border:1px solid var(--cyan);border-radius:50%;box-shadow:0 0 7px var(--cyan)}.objective-footer{display:flex;justify-content:space-between;margin-top:9px;color:#8f93a8;font:600 8px 'Space Grotesk';letter-spacing:1px}.distance{color:var(--cyan)}.event-banner{display:none;position:absolute;z-index:4;top:93px;left:50%;transform:translateX(-50%);width:min(610px,calc(100% - 32px));align-items:center;gap:13px;padding:11px 15px;border:1px solid rgba(255,129,160,.45);background:linear-gradient(100deg,rgba(38,17,39,.94),rgba(18,19,37,.92));box-shadow:0 0 32px rgba(227,72,133,.18)}.event-banner.active{display:flex;animation:eventIn .35s ease-out}@keyframes eventIn{from{transform:translate(-50%,-12px);opacity:0}to{transform:translate(-50%,0);opacity:1}}.event-emblem{width:34px;height:34px;border:1px solid #ff7ca3;color:#ff7798;display:grid;place-items:center;font:700 20px 'Space Grotesk';background:rgba(255,83,132,.12)}.event-copy{flex:1}.event-eyebrow{font:600 8px 'Space Grotesk';letter-spacing:1.5px;color:#ff94ae}.event-title{font:700 13px 'Space Grotesk';letter-spacing:1px;margin:2px 0}.event-sub{font-size:9px;color:#bbb3c4}.event-banner button{background:rgba(255,114,151,.1);border:1px solid rgba(255,124,159,.5);padding:9px 10px;color:#ffdce6;font:700 8px 'Space Grotesk';letter-spacing:.7px;cursor:pointer}.event-banner button span{margin-left:7px;color:#ff88a5}.world-label{position:absolute;left:50%;top:20%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;color:rgba(233,236,255,.83);font:600 9px 'Space Grotesk';letter-spacing:2px;text-shadow:0 1px 5px #000;pointer-events:none}.label-line{width:24px;height:1px;background:rgba(184,198,233,.55)}.toast{position:absolute;z-index:8;left:50%;bottom:136px;transform:translate(-50%,15px);padding:10px 17px;border:1px solid rgba(130,234,225,.35);background:rgba(10,18,31,.91);color:#e7f2ef;font-size:11px;opacity:0;pointer-events:none;transition:all .25s}.toast.show{opacity:1;transform:translate(-50%,0)}.toast-glyph{color:var(--cyan);margin-right:8px}.center-prompt{position:absolute;left:50%;top:48%;transform:translate(-50%,-50%);color:#fff;font:700 11px 'Space Grotesk';letter-spacing:1.5px;text-shadow:0 2px 8px black;pointer-events:none}.controls-hint{position:absolute;left:50%;bottom:105px;transform:translateX(-50%);color:rgba(230,232,245,.7);font:600 8px 'Space Grotesk';letter-spacing:1.4px;white-space:nowrap}.keycap{padding:4px 6px;border:1px solid rgba(220,228,255,.27);background:rgba(11,14,28,.53);font-size:8px;color:#f4f4fa}.hint-sep{margin:0 8px;color:#7a7d90}.bottom-ui{position:absolute;z-index:3;left:0;right:0;bottom:0;height:104px;display:flex;align-items:flex-end;justify-content:space-between;padding:0 34px 20px;background:linear-gradient(0deg,rgba(5,7,17,.75),transparent)}.bottom-left{display:flex;align-items:flex-end;gap:16px}.mini-map{position:relative;width:116px;height:90px;overflow:hidden;border:1px solid rgba(197,218,237,.4);background:rgba(12,18,31,.87);box-shadow:0 0 22px rgba(2,7,14,.4)}#minimap{width:100%;height:100%;display:block;opacity:.87}.map-compass{position:absolute;top:5px;left:6px;font:700 8px 'Space Grotesk';color:#fff}.map-caption{position:absolute;bottom:0;left:0;right:0;background:rgba(7,11,22,.86);padding:4px 7px;font:600 7px 'Space Grotesk';letter-spacing:1px;color:#bcc4d3}.map-caption span{float:right;color:var(--cyan)}.world-coords{display:flex;align-items:center;gap:9px;padding-bottom:4px}.coord-icon{font-size:20px;color:#87e8df}.world-coords div{font:600 8px 'Space Grotesk';letter-spacing:1.15px}.world-coords small{display:block;margin-top:5px;color:#a0a4b7;font-size:8px;letter-spacing:.7px}.combat-hud{display:flex;align-items:flex-end;gap:14px}.combo-readout{display:flex;flex-direction:column;align-items:center;margin-bottom:12px;width:54px}.combo-readout span{font:700 24px 'Space Grotesk';color:#f5e1b4;text-shadow:0 0 14px rgba(255,201,112,.25)}.combo-readout small{font:600 7px 'Space Grotesk';letter-spacing:1.5px;color:#a8a8b8}.combat-buttons{display:flex;gap:8px}.combat-btn{position:relative;width:65px;height:67px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;border:1px solid rgba(194,204,229,.23);background:rgba(17,21,38,.84);cursor:pointer;transition:transform .1s,background .2s;touch-action:manipulation}.combat-btn:active{transform:scale(.94);background:rgba(74,76,105,.85)}.combat-btn .btn-glyph{font-size:20px;color:#f1e5c7;line-height:1}.combat-btn b{font:700 8px 'Space Grotesk';letter-spacing:1px}.combat-btn small{position:absolute;right:5px;top:4px;font:600 7px 'Space Grotesk';color:#8e91a4}.skill-btn .btn-glyph{color:#a99bff}.dodge-btn .btn-glyph{color:#80e7df}.ult-btn{border-color:rgba(255,203,127,.48);background:rgba(40,31,34,.81)}.ult-btn .btn-glyph{color:#ffd489;text-shadow:0 0 12px #ecad54}.skill-charge{position:absolute;inset:auto 0 0;height:0%;background:rgba(134,117,255,.18);pointer-events:none;transition:height .25s}.touch-stick{display:none;position:absolute;z-index:5;left:28px;bottom:122px;width:120px;height:120px;touch-action:none}.stick-ring{position:absolute;inset:0;border:1px solid rgba(226,234,255,.23);border-radius:50%;background:rgba(11,16,31,.22);backdrop-filter:blur(2px)}.stick-knob{position:absolute;width:44px;height:44px;left:50%;top:50%;transform:translate(-50%,-50%);border-radius:50%;border:1px solid rgba(150,236,229,.6);background:rgba(111,208,206,.24);box-shadow:0 0 15px rgba(113,225,222,.14)}.mobile-actions{display:none;position:absolute;right:26px;bottom:132px}.mobile-interact{width:54px;height:54px;border-radius:50%;border:1px solid rgba(247,219,157,.65);background:rgba(39,31,34,.83);color:#f9d99a;font:700 15px 'Space Grotesk'}.mobile-interact small{display:block;font:600 6px 'Space Grotesk';letter-spacing:.6px}.overlay{position:absolute;z-index:12;inset:0;display:none;align-items:center;justify-content:center;background:rgba(5,7,16,.68);backdrop-filter:blur(9px);padding:20px}.overlay.open{display:flex;animation:fade .2s ease-out}@keyframes fade{from{opacity:0}to{opacity:1}}.panel{position:relative;width:min(600px,100%);padding:32px;background:linear-gradient(145deg,rgba(19,24,44,.98),rgba(12,16,31,.98));border:1px solid rgba(192,205,235,.22);box-shadow:0 30px 90px rgba(0,0,0,.5)}.close-panel{position:absolute;right:15px;top:12px;border:0;background:none;color:#b9bfd0;font-size:26px;cursor:pointer}.panel-kicker{font:600 9px 'Space Grotesk';letter-spacing:2px;color:var(--cyan)}.panel h2{font:600 31px 'Space Grotesk';letter-spacing:-1px;margin:9px 0}.panel p{font-size:12px;color:#acb2c4;line-height:1.6;margin:0 0 20px}.map-panel{width:min(720px,100%)}#big-map{display:block;width:100%;height:auto;border:1px solid rgba(193,211,235,.2);background:#10182a}.atlas-legend{display:flex;gap:18px;margin-top:12px;font:600 8px 'Space Grotesk';letter-spacing:1px;color:#b7bfd0}.atlas-legend span:nth-child(1){color:#72e8d7}.atlas-legend span:nth-child(2){color:#d8b8ff}.atlas-legend span:nth-child(3){color:#ff849f}.realm-list{display:flex;flex-wrap:wrap;gap:8px 18px;margin-top:17px;color:#c0c5d3;font:600 8px 'Space Grotesk';letter-spacing:.8px}.awakening-panel{width:min(620px,100%)}.awakening-options{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:23px 0}.awaken-option{min-height:145px;padding:14px 12px;border:1px solid rgba(187,198,228,.2);background:rgba(36,42,66,.3);display:flex;flex-direction:column}.awaken-option>span{font-size:22px;color:#c1a8ff}.awaken-option b{font:700 10px 'Space Grotesk';letter-spacing:1px;margin-top:9px}.awaken-option small{color:#a7acbf;font-size:9px;margin-top:5px}.awaken-option i{font-style:normal;color:#74ded6;font-size:8px;margin-top:auto;padding-top:12px}.primary-action{width:100%;padding:13px;border:1px solid rgba(115,232,224,.55);background:rgba(78,180,175,.12);font:700 9px 'Space Grotesk';letter-spacing:1.5px;cursor:pointer}.primary-action span{float:right;color:var(--cyan)}.choice-panel{width:min(470px,100%)}.choice-button{display:block;text-align:left;width:100%;position:relative;margin:9px 0;padding:14px 13px 14px 45px;border:1px solid rgba(189,202,231,.2);background:rgba(38,43,65,.4);cursor:pointer}.choice-button:hover{border-color:rgba(116,231,220,.6)}.choice-button span{position:absolute;left:14px;top:15px;color:var(--cyan);font:700 10px 'Space Grotesk'}.choice-button b{display:block;font:600 11px 'Space Grotesk'}.choice-button small{display:block;margin-top:5px;color:#a2a8ba;font-size:9px}.intro{position:absolute;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;text-align:center;background:linear-gradient(90deg,rgba(7,9,20,.58),rgba(7,9,20,.22),rgba(7,9,20,.58));transition:opacity .8s,visibility .8s}.intro.hidden{opacity:0;visibility:hidden;pointer-events:none}.intro-content{margin-top:20px}.intro-sigil{color:var(--cyan);font-size:27px;text-shadow:0 0 25px #70e7da;margin-bottom:20px}.intro-kicker{font:600 9px 'Space Grotesk';letter-spacing:3px;color:#a8b3c5}.intro h1{font:600 clamp(38px,6.4vw,73px)/.98 'Space Grotesk';letter-spacing:-3px;margin:16px 0;color:#f4f3f2;text-shadow:0 4px 28px rgba(0,0,0,.45)}.intro h1 em{font-style:normal;color:#a5e5e0}.intro-content p{font-size:12px;line-height:1.7;color:#c0c4d2}.intro-content button{margin-top:15px;width:224px;padding:14px 17px;text-align:left;border:1px solid rgba(117,232,221,.68);background:rgba(74,179,174,.22);font:700 10px 'Space Grotesk';letter-spacing:1.5px;cursor:pointer;box-shadow:0 0 28px rgba(88,213,205,.12)}.intro-content button span{float:right;color:var(--cyan)}.intro-foot{margin-top:30px;color:#9196a9;font:600 8px 'Space Grotesk';letter-spacing:1.6px}.intro-foot span{margin:0 7px;color:#72e8dc}
@media(max-width:700px){.topbar{height:58px;padding:0 16px}.brand-mark{width:31px;height:31px}.brand-name{font-size:10px;letter-spacing:1.3px}.brand-kicker{font-size:7px;letter-spacing:1.4px}.realm-chip{top:68px;left:auto;right:16px;transform:none;font-size:8px;padding:7px 9px;background:rgba(10,14,28,.57);border:1px solid rgba(210,221,245,.14)}.icon-button{width:33px;height:33px}.hud-left{top:74px;left:15px;width:190px}.player-card{gap:8px;padding-bottom:9px}.avatar{width:31px;height:31px;font-size:17px}.player-name{font-size:9px}.player-sub{font-size:7px}.vital{margin-top:9px}.vital-head{font-size:7px}.bar{margin-top:4px}.energy-vital{margin-top:7px}.awakening-card{margin-top:9px;padding:7px}.awaken-icon{font-size:16px}.path-progress{width:95px}.objective-card{right:12px;top:auto;bottom:230px;width:190px;padding:10px}.objective-title{font-size:10px;margin:5px 0}.objective-copy{font-size:8px;line-height:1.4}.objective-step{margin-top:7px;padding:6px;font-size:8px}.objective-footer{font-size:7px;margin-top:6px}.world-label{top:26%;font-size:8px}.bottom-ui{height:102px;padding:0 13px 12px}.bottom-left{gap:8px}.mini-map{width:77px;height:68px}.map-caption{font-size:6px;padding:3px 4px}.world-coords{gap:5px}.coord-icon{font-size:15px}.world-coords div{font-size:7px}.world-coords small{font-size:6px}.combat-hud{gap:5px}.combo-readout{width:28px;margin-bottom:9px}.combo-readout span{font-size:18px}.combo-readout small{font-size:6px}.combat-buttons{gap:4px}.combat-btn{width:48px;height:52px}.combat-btn .btn-glyph{font-size:17px}.combat-btn b{font-size:7px}.combat-btn small{font-size:6px}.controls-hint{display:none}.touch-stick{display:block}.mobile-actions{display:block}.event-banner{top:107px;padding:8px;gap:7px}.event-emblem{width:27px;height:27px;font-size:16px}.event-eyebrow{font-size:7px}.event-title{font-size:10px}.event-sub{font-size:8px}.event-banner button{font-size:6px;padding:8px 6px}.panel{padding:25px 20px}.panel h2{font-size:26px}.panel p{font-size:11px}.awakening-options{gap:6px}.awaken-option{padding:9px;min-height:130px}.awaken-option b{font-size:8px}.awaken-option small,.awaken-option i{font-size:7px}.realm-list{font-size:7px;gap:8px}.atlas-legend{gap:10px;font-size:7px}.intro h1{letter-spacing:-2px}.intro-foot{font-size:7px;letter-spacing:1px}.toast{bottom:171px;max-width:85%;white-space:nowrap;font-size:10px}.event-banner.active~.toast{bottom:171px}}
