import * as THREE from 'https://unpkg.com/three@0.164.1/build/three.module.js';

const canvas=document.querySelector('#world');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.background=new THREE.Color('#10172a');scene.fog=new THREE.FogExp2('#12192b',.0085);
const camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.1,500);
scene.add(new THREE.HemisphereLight(0xa6c8ec,0x211c31,2));
const moon=new THREE.DirectionalLight(0xb4d8ff,2.4);moon.position.set(-35,70,25);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);moon.shadow.camera.left=-90;moon.shadow.camera.right=90;moon.shadow.camera.top=90;moon.shadow.camera.bottom=-90;scene.add(moon);
const fill=new THREE.PointLight(0x71dcd7,35,90);fill.position.set(-12,10,2);scene.add(fill);
const world=new THREE.Group();scene.add(world);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const M={ground:mat('#1d2634'),stone:mat('#394250'),dark:mat('#151c2d'),neon:mat('#293451'),cyan:mat('#5de0dc',.36,.3),pink:mat('#ec6caa',.4,.15),gold:mat('#f2c477',.43,.2),leaf:mat('#273c38'),leaf2:mat('#456359'),bark:mat('#332b38'),shrine:mat('#71604b'),red:mat('#713e3c'),lava:mat('#ff714b',.45),snow:mat('#d6e5ed'),ice:mat('#79c5dc',.35,.2),purple:mat('#8d68cf',.4,.2),white:mat('#ecf2f5'),black:mat('#181827')};
function mesh(geo,material,x,y,z,group=world){const o=new THREE.Mesh(geo,material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;group.add(o);return o}
function box(x,y,z,sx,sy,sz,material,group=world){return mesh(new THREE.BoxGeometry(sx,sy,sz),material,x,y,z,group)}
function cyl(x,y,z,r1,r2,h,material,segments=8,group=world){return mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material,x,y,z,group)}
function sphere(x,y,z,r,material,group=world){return mesh(new THREE.IcosahedronGeometry(r,1),material,x,y,z,group)}
// Endless-looking fractured plain and colored realm islands.
box(0,-1.15,0,230,1.2,230,M.ground);
const zones=[
 {name:'NEON CITY',x:-35,z:-30,r:35,color:'#222c48',accent:'#55e4dd',kind:'city'},
 {name:'CURSED FOREST',x:37,z:-31,r:33,color:'#20382f',accent:'#a881e9',kind:'forest'},
 {name:'FALLEN SHRINE',x:-37,z:34,r:32,color:'#423b38',accent:'#e5bf7d',kind:'shrine'},
 {name:'INFERNO ZONE',x:39,z:35,r:34,color:'#422c32',accent:'#ff7654',kind:'inferno'},
 {name:'FROZEN KINGDOM',x:0,z:-78,r:27,color:'#344650',accent:'#90e6ef',kind:'frozen'}
];
