import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

// Shattered Realms: a self-contained, procedural third-person RPG prototype.
const canvas = document.querySelector('#world');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#101827');
scene.fog = new THREE.FogExp2('#101827', 0.0068);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, 0.1, 420);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.18;

scene.add(new THREE.HemisphereLight('#a9c5e8', '#161626', 2.0));
const moon = new THREE.DirectionalLight('#c6d9ff', 2.4);
moon.position.set(-35, 75, 35); moon.castShadow = true;
moon.shadow.mapSize.set(1024, 1024); moon.shadow.camera.left = -110; moon.shadow.camera.right = 110;
moon.shadow.camera.top = 110; moon.shadow.camera.bottom = -110; scene.add(moon);
const fill = new THREE.PointLight('#55daca', 32, 90); fill.position.set(-39, 8, 0); scene.add(fill);
const world = new THREE.Group(); scene.add(world);
const clock = new THREE.Clock();
const M = (color, roughness=.8, extra={}) => new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const mat = {
  ground: M('#182433'), road: M('#253044'), city: M('#26334a'), neon: M('#52e7dc',.32,{emissive:'#1a8b86',emissiveIntensity:1.1}),
  bark: M('#382d38'), leaf: M('#214d47'), leaf2: M('#326354'), stone: M('#695d64'), gold: M('#d5a96c'), ice: M('#9dd8ea',.28,{metalness:.1,emissive:'#31627a',emissiveIntensity:.3}),
  ember: M('#a84f42',.42,{emissive:'#57231d',emissiveIntensity:.55}), violet: M('#b684ff',.26,{emissive:'#7548c9',emissiveIntensity:1.25}), white: M('#fff5ec'),
  dark: M('#1b1b2b'), cloth: M('#242c49'), trim: M('#49d8d0',.38,{emissive:'#137f7d',emissiveIntensity:.45})
};
const zones = [
  {name:'NEON CITY',x:-43,z:0,r:25,kind:'city',accent:'#55e9df',ground:'#1b293d'},
  {name:'CURSED FOREST',x:-23,z:-39,r:25,kind:'forest',accent:'#83d3a6',ground:'#182b2a'},
  {name:'FALLEN SHRINE',x:0,z:0,r:25,kind:'shrine',accent:'#e9c88b',ground:'#302b31'},
  {name:'INFERNO ZONE',x:32,z:-36,r:25,kind:'inferno',accent:'#ff8a70',ground:'#342322'},
  {name:'FROZEN KINGDOM',x:48,z:5,r:26,kind:'ice',accent:'#a6eaff',ground:'#243542'}
];
const matGround = new THREE.Mesh(new THREE.PlaneGeometry(250,250), mat.ground);
matGround.rotation.x=-Math.PI/2; matGround.position.y=-.14; matGround.receiveShadow=true; world.add(matGround);
const zonesMesh=[];
for(const z of zones){
  const disc=new THREE.Mesh(new THREE.CircleGeometry(z.r,64),M(z.ground)); disc.rotation.x=-Math.PI/2; disc.position.set(z.x,-.08,z.z); disc.receiveShadow=true; world.add(disc); zonesMesh.push(disc);
  const rim=new THREE.Mesh(new THREE.RingGeometry(z.r-.35,z.r,64),M(z.accent,.55,{emissive:z.accent,emissiveIntensity:.16,transparent:true,opacity:.65})); rim.rotation.x=-Math.PI/2;rim.position.set(z.x,.02,z.z);world.add(rim);
}
// Fractured causeways visually connect the five playable biomes.
function road(ax,az,bx,bz,width=4){const dx=bx-ax,dz=bz-az,len=Math.hypot(dx,dz);const m=new THREE.Mesh(new THREE.PlaneGeometry(width,len),mat.road);m.rotation.x=-Math.PI/2;m.rotation.z=-Math.atan2(dx,dz);m.position.set((ax+bx)/2,.01,(az+bz)/2);world.add(m);}
road(-43,0,0,0,4);road(-23,-39,0,0,3.5);road(0,0,32,-36,3.5);road(0,0,48,5,4);
// Procedural landmarks: neon towers, haunted woods, shrine gates, infernal spires, ice monoliths.
const rand=(seed)=>{let x=Math.sin(seed*127.1+311.7)*43758.5453;return x-Math.floor(x)};
function box(parent,geo,material,x,y,z,rx=0,ry=0,rz=0){const o=new THREE.Mesh(geo,material);o.position.set(x,y,z);o.rotation.set(rx,ry,rz);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
function cylinder(parent,r1,r2,h,material,x,y,z,segments=8){return box(parent,new THREE.CylinderGeometry(r1,r2,h,segments),material,x,y,z);}
// City block
for(let i=0;i<18;i++){const a=i*2.399,rad=5+rand(i+8)*16,x=-43+Math.cos(a)*rad,z=Math.sin(a)*rad,h=5+rand(i+31)*17,w=2.2+rand(i+51)*3;box(world,new THREE.BoxGeometry(w,h,w),M(i%3?'#29354b':'#35425a'),x,h/2,z);for(let y=2;y<h-1;y+=2.4){const strip=box(world,new THREE.BoxGeometry(w+.025,.12,.08),mat.neon,x,y,z+w/2+.05);strip.material=mat.neon;}}
for(let i=0;i<7;i++){const x=-50+i*2.2;box(world,new THREE.BoxGeometry(.13,7,.13),mat.gold,x,3.5,4);box(world,new THREE.BoxGeometry(.55,.14,.16),mat.neon,x,6.7,4);}
// Trees
for(let i=0;i<33;i++){const a=i*2.4,r=7+rand(i+111)*17,x=-23+Math.cos(a)*r,z=-39+Math.sin(a)*r,h=3+rand(i+131)*2;cylinder(world,.34,.55,h,mat.bark,x,h/2,z);const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(1.7+rand(i+151)*.8,1),i%3?mat.leaf:mat.leaf2);crown.position.set(x,h+1,z);crown.scale.y=1.25;crown.castShadow=true;world.add(crown);}
// Shrine torii and scattered pillars
for(let i=0;i<5;i++){const x=-9+i*4.5,z=-4;box(world,new THREE.BoxGeometry(.55,5,.55),mat.stone,x,2.5,z);box(world,new THREE.BoxGeometry(5.2,.5,.85),mat.gold,x,5,z);box(world,new THREE.BoxGeometry(6,.22,1),M('#9f5656'),x,5.4,z);}
for(let i=0;i<9;i++){const x=(rand(i+212)-.5)*34,z=(rand(i+233)-.5)*34;if(Math.hypot(x,z)<8)continue;const h=2+rand(i+255)*5;cylinder(world,.7,.85,h,mat.stone,x,h/2,z,6);}
// Inferno spires and lava seams
for(let i=0;i<17;i++){const a=i*2.4,r=5+rand(i+311)*18,x=32+Math.cos(a)*r,z=-36+Math.sin(a)*r,h=3+rand(i+333)*9;const sp=box(world,new THREE.ConeGeometry(1.4+rand(i+355),h,5),mat.ember,x,h/2,z,0,rand(i+388),0);sp.rotation.z=(rand(i+391)-.5)*.22;}
for(let i=0;i<5;i++){const seam=box(world,new THREE.BoxGeometry(.17,.04,13+rand(i+411)*8),M('#ff7956',.4,{emissive:'#ff3e24',emissiveIntensity:1.4}),22+i*4,.08,-43+i*3);seam.rotation.y=.4;}
// Ice monoliths
for(let i=0;i<15;i++){const a=i*2.4,r=6+rand(i+511)*19,x=48+Math.cos(a)*r,z=5+Math.sin(a)*r,h=4+rand(i+533)*10;cylinder(world,.35,1.3,h,mat.ice,x,h/2,z,5);}
// Floating shards throughout the frontier.
for(let i=0;i<34;i++){const x=(rand(i+600)-.5)*130,z=(rand(i+700)-.5)*110;if(Math.hypot(x,z)>104)continue;const shard=box(world,new THREE.OctahedronGeometry(.55+rand(i+800)*.85),i%4===0?mat.violet:mat.neon,x,2+rand(i+900)*8,z,0,rand(i+1000)*3,0);shard.userData.float=rand(i+1100)*6;}
// Starfield
const starsGeo=new THREE.BufferGeometry(),starPoints=[];for(let i=0;i<650;i++){let a=rand(i+1200)*Math.PI*2,r=80+rand(i+1300)*180;starPoints.push(Math.cos(a)*r,24+rand(i+1400)*95,Math.sin(a)*r);}starsGeo.setAttribute('position',new THREE.Float32BufferAttribute(starPoints,3));scene.add(new THREE.Points(starsGeo,new THREE.PointsMaterial({color:'#b8d6ff',size:.42,transparent:true,opacity:.8})));

const player=new THREE.Group();world.add(player);
const torso=box(player,new THREE.CapsuleGeometry(.43,.8,4,8),mat.cloth,0,1.2,0);
const head=box(player,new THREE.SphereGeometry(.31,12,10),M('#e7c7bd'),0,2.05,0);head.scale.set(.86,1.05,.8);
const hair=box(player,new THREE.SphereGeometry(.34,10,8),M('#17182b'),0,2.25,-.045);hair.scale.set(1,.58,1.04);
const legs=[-1,1].map((s)=>box(player,new THREE.CapsuleGeometry(.16,.62,3,6),M('#141a2d'),s*.22,.48,0));
const arms=[-1,1].map((s)=>box(player,new THREE.CapsuleGeometry(.13,.62,3,6),M('#323957'),s*.55,1.27,0,0,0,s*.12));
const aura=new THREE.PointLight('#5ce4de',3,5);aura.position.y=1.2;player.add(aura);
player.position.set(-42,0,1);player.rotation.y=0;
function makeFigure(material){const g=new THREE.Group();const body=box(g,new THREE.IcosahedronGeometry(1,1),material,0,1.65,0);body.scale.set(.75,1.2,.65);const eyeMat=M('#ff637e',.25,{emissive:'#ff294c',emissiveIntensity:1.8});for(const s of [-1,1])box(g,new THREE.SphereGeometry(.1,8,6),eyeMat,s*.23,2.05,.5);return {root:g,body};}
const traveler= new THREE.Group();world.add(traveler);traveler.position.set(-34,0,8);
const keeper=box(traveler,new THREE.CapsuleGeometry(.28,.65,4,8),M('#c1a77a'),0,1,0);box(traveler,new THREE.SphereGeometry(.23,10,8),M('#e5c4a4'),0,1.67,0);

const state={hp:100,energy:60,ult:0,combo:0,comboTimer:0,attackCd:0,skillCd:0,dodgeCd:0,dodge:0,invuln:0,walk:0,started:false,moveX:0,moveZ:0,clues:0,discoveries:0,bossKills:0,choice:null,guardian:false,clock,};
let markers=[],enemies=[],effects=[],eventStarted=false,boss=null,bossDefeated=false,eventTimer=28,lastRegion='';
const mini=document.querySelector('#minimap'),miniCtx=mini.getContext('2d'),bigMap=document.querySelector('#big-map'),bigCtx=bigMap.getContext('2d');
function makeMarker(x,z,secret=false){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);const crystal=box(g,new THREE.OctahedronGeometry(.55,0),secret?mat.violet:mat.gold,0,1.05,0,0,0,.4);const ring=new THREE.Mesh(new THREE.TorusGeometry(.92,.055,6,24),M(secret?'#bc8dff':'#f5d589',.4,{emissive:secret?'#8b51da':'#996f36',emissiveIntensity:.7}));ring.rotation.x=Math.PI/2;ring.position.y=.12;g.add(ring);g.userData={x,z,secret,found:false,crystal,ring,type:secret?'secret':'clue'};markers.push(g);return g;}
makeMarker(-48,-9);makeMarker(-39,10);makeMarker(-31,-5);makeMarker(-10,-30,true);makeMarker(11,14,true);makeMarker(43,-8,true);
function toast(text){const el=document.querySelector('#toast');document.querySelector('#toast-text').textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2500);}
function showPrompt(text){const el=document.querySelector('#center-prompt');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1100);}
function drawMap(ctx,w,h,large=false){ctx.clearRect(0,0,w,h);ctx.fillStyle='#111b2b';ctx.fillRect(0,0,w,h);ctx.save();ctx.translate(w/2,h/2);ctx.scale(large?3.2:.68,large?3.2:.68);for(const z of zones){ctx.beginPath();ctx.arc(z.x,z.z,z.r,0,Math.PI*2);ctx.fillStyle=z.kind==='city'?'#273856':z.kind==='forest'?'#264238':z.kind==='shrine'?'#55473c':z.kind==='inferno'?'#573537':'#3b5863';ctx.fill();ctx.strokeStyle=z.accent;ctx.globalAlpha=.6;ctx.lineWidth=.35;ctx.stroke();ctx.globalAlpha=1;}ctx.strokeStyle='rgba(184,202,223,.35)';ctx.lineWidth=1;ctx.beginPath();zones.forEach(z=>{ctx.moveTo(z.x,z.z);ctx.lineTo(0,0)});ctx.stroke();for(const m of markers){if(m.userData.found)continue;ctx.fillStyle=m.userData.secret?'#cca2ff':'#f2cd84';ctx.beginPath();ctx.arc(m.userData.x,m.userData.z,large?1.2:.9,0,Math.PI*2);ctx.fill();}if(eventStarted&&!bossDefeated){ctx.fillStyle='#ff809f';ctx.beginPath();ctx.arc(17,7,large?2.2:1.6,0,Math.PI*2);ctx.fill();}ctx.fillStyle='#6ef1df';ctx.beginPath();ctx.arc(player.position.x,player.position.z,large?1.8:1.5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e8fffb';ctx.lineWidth=.6;ctx.stroke();ctx.restore();if(large){ctx.fillStyle='rgba(222,231,247,.7)';ctx.font='600 11px Space Grotesk';ctx.fillText('N',w/2-3,18);}}
function regionAt(x,z){let best='THE SHATTERED CROSSROADS',d=1e9;for(const zone of zones){let v=Math.hypot(x-zone.x,z-zone.z);if(v<zone.r+3&&v<d){best=zone.name;d=v}}return best;}

content.text:
 overlay
.overlay{position:absolute;z-index:12;inset:0;display:none;align-items:center;justify-content:center;background:rgba(5,7,16,.68);backdrop-filter:blur(9px);padding:20px}
.overlay.open{display:flex;animation:fade .2s ease-out}

 event-banner
.event-banner{display:none;position:absolute;z-index:4;top:93px;left:50%;transform:translateX(-50%);width:min(610px,calc(100% - 32px));align-items:center;gap:13px;padding:11px 15px;border:1px solid rgba(255,129,160,.45);background:linear-gradient(100deg,rgba(38,17,39,.94),rgba(18,19,37,.92));box-shadow:0 0 32px rgba(227,72,133,.18)}
.event-banner.active{display:flex;animation:eventIn .35s ease-out}
.event-banner button{background:rgba(255,114,151,.1);border:1px solid rgba(255,124,159,.5);padding:9px 10px;color:#ffdce6;font:700 8px 'Space Grotesk';letter-spacing:.7px;cursor:pointer}
.event-banner button span{margin-left:7px;color:#ff88a5}
.event-banner{top:107px;padding:8px;gap:7px}
.event-banner button{font-size:6px;padding:8px 6px}
.event-banner.active~.toast{bottom:171px}

 toast
.toast{position:absolute;z-index:8;left:50%;bottom:136px;transform:translate(-50%,15px);padding:10px 17px;border:1px solid rgba(130,234,225,.35);background:rgba(10,18,31,.91);color:#e7f2ef;font-size:11px;opacity:0;pointer-events:none;transition:all .25s}
.toast.show{opacity:1;transform:translate(-50%,0)}
.toast-glyph{color:var(--cyan);margin-right:8px}
.toast{bottom:171px;max-width:85%;white-space:nowrap;font-size:10px}
.event-banner.active~.toast{bottom:171px}

 center-prompt
.center-prompt{position:absolute;left:50%;top:48%;transform:translate(-50%,-50%);color:#fff;font:700 11px 'Space Grotesk';letter-spacing:1.5px;text-shadow:0 2px 8px black;pointer-events:none}

 intro
.intro{position:absolute;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;text-align:center;background:linear-gradient(90deg,rgba(7,9,20,.58),rgba(7,9,20,.22),rgba(7,9,20,.58));transition:opacity .8s,visibility .8s}
.intro.hidden{opacity:0;visibility:hidden;pointer-events:none}
.intro-content{margin-top:20px}
.intro-sigil{color:var(--cyan);font-size:27px;text-shadow:0 0 25px #70e7da;margin-bottom:20px}
.intro-kicker{font:600 9px 'Space Grotesk';letter-spacing:3px;color:#a8b3c5}
.intro h1{font:600 clamp(38px,6.4vw,73px)/.98 'Space Grotesk';letter-spacing:-3px;margin:16px 0;color:#f4f3f2;text-shadow:0 4px 28px rgba(0,0,0,.45)}
.intro h1 em{font-style:normal;color:#a5e5e0}
.intro-content p{font-size:12px;line-height:1.7;color:#c0c4d2}
.intro-content button{margin-top:15px;width:224px;padding:14px 17px;text-align:left;border:1px solid rgba(117,232,221,.68);background:rgba(74,179,174,.22);font:700 10px 'Space Grotesk';letter-spacing:1.5px;cursor:pointer;box-shadow:0 0 28px rgba(88,213,205,.12)}
.intro-content button span{float:right;color:var(--cyan)}
.intro-foot{margin-top:30px;color:#9196a9;font:600 8px 'Space Grotesk';letter-spacing:1.6px}
.intro-foot span{margin:0 7px;color:#72e8dc}
.intro h1{letter-spacing:-2px}
.intro-foot{font-size:7px;letter-spacing:1px}

 touch-stick
.touch-stick{display:none;position:absolute;z-index:5;left:28px;bottom:122px;width:120px;height:120px;touch-action:none}
.touch-stick{display:block}
.touch-stick{width:90px;height:90px;left:18px;bottom:87px}

 awake
