function updateVitals(){document.querySelector('#hp-text').textContent=`${Math.ceil(state.hp)} / 100`;document.querySelector('#hp-bar').style.width=`${Math.max(0,state.hp)}%`;document.querySelector('#energy-text').textContent=`${Math.ceil(state.energy)} / 60`;document.querySelector('#energy-bar').style.width=`${state.energy/60*100}%`;document.querySelector('#skill-charge').style.height=`${state.skillCd?Math.max(0,100-state.skillCd/5.5*100):0}%`;document.querySelector('#ult-btn').style.opacity=state.ult>=100?'1':'.65';document.querySelector('#ult-btn').querySelector('small').textContent=state.ult>=100?'READY':`${Math.floor(state.ult)}%`;}
function refreshAwakening(){let path='UNWRITTEN',pct=0;if(state.bossKills){path='BERSERKER';pct=Math.min(100,state.bossKills*100);}else if(state.discoveries>=3){path='VOID WALKER';pct=Math.min(95,50+state.discoveries*12);}else if(state.guardian){path='GUARDIAN';pct=65;}else{path='UNWRITTEN';pct=Math.min(48,state.discoveries*16+state.clues*6);}document.querySelector('#path-name').textContent=path;document.querySelector('#awakening-label').textContent=path==='UNWRITTEN'?'UNAWAKENED':`${path} · AWAKENED`;document.querySelector('#path-progress').style.width=`${pct}%`;document.querySelector('#path-percent').textContent=`${pct}%`;document.querySelector('#boss-trait').textContent=`${state.bossKills} / 1 boss encounters`;document.querySelector('#explore-trait').textContent=`${state.discoveries} / 3 discoveries`;}
function refreshPrompt(){let nearest=null,dist=1000;for(const m of markers){if(m.userData.found)continue;const d=Math.hypot(player.position.x-m.userData.x,player.position.z-m.userData.z);if(d<dist){dist=d;nearest=m;}}let travelerD=player.position.distanceTo(traveler.position);let prompt='';if(state.clues>=3&&!state.choice&&travelerD<5)prompt='[ E ]  SPEAK WITH THE STATION KEEPER';else if(dist<4)prompt=`[ E ]  DISCOVER ${nearest.userData.secret?'HIDDEN SECRET':'SIGNAL FRAGMENT'}`;else if(travelerD<5&&!state.choice)prompt='[ E ]  SPEAK';document.querySelector('#center-prompt').textContent=prompt;document.querySelector('#center-prompt').classList.toggle('show',Boolean(prompt));const objectiveMarker=markers.find(m=>!m.userData.found&&m.userData.type==='clue');if(objectiveMarker){let dx=objectiveMarker.userData.x-player.position.x,dz=objectiveMarker.userData.z-player.position.z,meters=Math.round(Math.hypot(dx,dz));let dir=Math.abs(dx)>Math.abs(dz)?(dx>0?'E':'W'):(dz>0?'S':'N');document.querySelector('#objective-distance').textContent=`${dir} ${meters}m`;}else{document.querySelector('#objective-distance').textContent=state.clues>=3?'RETURN':'COMPLETE';}}
function makeEnemy(name,x,z,bossFlag=false){const figure=makeFigure(bossFlag?M('#402248',.3,{emissive:'#8b315f',emissiveIntensity:1}):M('#263947',.48,{emissive:'#315c60',emissiveIntensity:.7}));figure.root.position.set(x,0,z);world.add(figure.root);if(bossFlag){const ring=new THREE.Mesh(new THREE.TorusGeometry(1.7,.1,8,36),M('#ff709d',.25,{emissive:'#ff3c75',emissiveIntensity:1.6}));ring.position.y=2.1;figure.root.add(ring);figure.ring=ring;}const e={name,root:figure.root,body:figure.body,glow:figure.body.material,ring:figure.ring||null,alive:true,boss:bossFlag,hp:bossFlag?340:34,maxHp:bossFlag?340:34,phase:1,attack:2.5,exposed:0,stagger:0,hitFlash:0};enemies.push(e);if(bossFlag)boss=e;return e;}
function spawnBoss(){if(eventStarted||bossDefeated)return;eventStarted=true;document.querySelector('#event-banner').classList.add('active');makeEnemy('VOID TITAN',17,7,true);toast('The Void Titan has crossed into the frontier.');drawMap(bigCtx,bigMap.width,bigMap.height,true);}
function addEffect(object,kind,life,vel=null){world.add(object);effects.push({object,kind,life,vel:vel||new THREE.Vector3()});}
function spawnRing(position,color='#ff7398'){const ring=new THREE.Mesh(new THREE.RingGeometry(.5,.8,48),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.8,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.set(position.x,.13,position.z);addEffect(ring,'ring',.55);}
function nearestEnemy(max=5){let chosen=null,distance=max;for(const e of enemies){if(!e.alive)continue;const d=Math.hypot(player.position.x-e.root.position.x,player.position.z-e.root.position.z);if(d<distance){chosen=e;distance=d;}}return chosen;}
function damageEnemy(e,damage,heavy=false){if(!e||!e.alive)return;e.hp-=damage;e.hitFlash=.14;e.exposed=Math.max(e.exposed,heavy?.85:.22);state.ult=Math.min(100,state.ult+(e.boss?8:12));state.combo++;state.comboTimer=2.5;document.querySelector('#combo-count').textContent=String(state.combo).padStart(2,'0');for(let i=0;i<6;i++){const p=new THREE.Mesh(new THREE.SphereGeometry(.07,5,4),i%2?mat.gold:mat.neon);p.position.copy(e.root.position).add(new THREE.Vector3((Math.random()-.5)*1.2,1.3+Math.random(),(Math.random()-.5)*1.2));addEffect(p,'particle',.6,new THREE.Vector3((Math.random()-.5)*4,Math.random()*4,(Math.random()-.5)*4));}if(e.boss){if(e.hp<e.maxHp*.62&&e.phase===1){e.phase=2;toast('The Titan fractures · phase II');e.stagger=1.2;}if(e.hp<e.maxHp*.28&&e.phase===2){e.phase=3;toast('The core opens · phase III');e.stagger=1.5;}document.querySelector('#event-sub').textContent=`VOID TITAN · CORE ${Math.max(0,Math.ceil(e.hp/e.maxHp*100))}% · PHASE ${e.phase}`;}if(e.hp<=0){e.alive=false;world.remove(e.root);if(e.boss){bossDefeated=true;state.bossKills++;state.ult=100;document.querySelector('#event-sub').textContent='VOID TITAN · DEFEATED';document.querySelector('#event-action').textContent='RIFT SEALED ✓';toast('The Titan falls. Your awakening has begun.');refreshAwakening();}else toast('Curse hound dispersed.');}}
function attack(){if(!state.started||state.attackCd>0)return;state.attackCd=.42;const target=nearestEnemy(5.5);const slash=new THREE.Mesh(new THREE.TorusGeometry(1.05,.045,5,28,Math.PI*1.35),M('#8cf5e8',.3,{emissive:'#52d8d1',emissiveIntensity:1.8,transparent:true,opacity:.9}));slash.position.set(player.position.x,1.15,player.position.z);slash.rotation.set(Math.PI/2,0,player.rotation.y-.6);addEffect(slash,'slash',.25);if(target){const d=player.position.distanceTo(target.root.position);if(d<5.5)damageEnemy(target,target.boss?(target.exposed>0?24:12):18);}}
function skill(){if(!state.started||state.skillCd>0||state.energy<18)return;state.energy-=18;state.skillCd=5.5;const rift=new THREE.Mesh(new THREE.TorusGeometry(2.2,.12,8,40),M('#bd8dff',.3,{emissive:'#9e64ff',emissiveIntensity:2,transparent:true,opacity:.9}));rift.rotation.x=Math.PI/2;rift.position.set(player.position.x,.35,player.position.z);addEffect(rift,'rift',.6);for(const e of enemies){if(!e.alive)continue;const d=player.position.distanceTo(e.root.position);if(d<8){e.exposed=3;e.stagger=.9;damageEnemy(e,e.boss?26:30,true);e.exposed=3;}}toast('Rift burst · nearby enemies exposed.');updateVitals();}
function dodge(){if(!state.started||state.dodgeCd>0)return;state.dodgeCd=.9;state.dodge=.24;state.invuln=.48;const move=new THREE.Vector3(state.moveX,state.moveZ,0); // overwritten below with world X/Z
let mx=state.moveX,mz=state.moveZ;if(Math.hypot(mx,mz)<.1){mx=Math.sin(player.rotation.y);mz=Math.cos(player.rotation.y);}player.userData.dodgeDir=new THREE.Vector3(mx,0,mz).normalize();}
function awaken(){if(!state.started||state.ult<100)return;state.ult=0;state.invuln=1.2;const pulse=new THREE.Mesh(new THREE.SphereGeometry(1,20,16),new THREE.MeshBasicMaterial({color:'#8fffee',transparent:true,opacity:.35,wireframe:true}));pulse.position.set(player.position.x,1,player.position.z);pulse.scale.setScalar(.2);addEffect(pulse,'rift',.6);for(const e of enemies){if(e.alive&&player.position.distanceTo(e.root.position)<11){e.exposed=2.5;damageEnemy(e,e.boss?65:60,true);e.exposed=2.5;}}toast('AWAKENING · the frontier answers.');updateVitals();}
function interact(){if(!state.started)return;const travelerD=player.position.distanceTo(traveler.position);if(travelerD<5&&!state.choice){if(state.clues>=3){document.querySelector('#choice-overlay').classList.add('open');return;}toast('The station keeper needs three signal fragments.');return;}let found=null,d=4;for(const m of markers){if(m.userData.found)continue;const distance=Math.hypot(player.position.x-m.userData.x,player.position.z-m.userData.z);if(distance<d){found=m;d=distance;}}if(found){found.userData.found=true;found.visible=false;if(found.userData.secret){state.discoveries++;toast('Hidden memory found · the realms remember you.');}else{state.clues++;document.querySelector('#clue-count').textContent=`CLUES ${state.clues} / 3`;toast(`Signal fragment recovered · ${state.clues} / 3`);}if(state.clues>=3){document.querySelector('#objective-title').textContent='A CHOICE AT THE STATION';document.querySelector('#objective-copy').textContent='The keeper waits at the neon crossing. The last shard could save a stranger — or open a way forward.';document.querySelector('#objective-step').textContent='Return to the station keeper in Neon City';}refreshAwakening();drawMap(bigCtx,bigMap.width,bigMap.height,true);return;}if(travelerD<5&&state.choice){toast('The keeper nods toward the open frontier.');return;}toast('Nothing nearby to interact with. Follow the signal fragments on your map.');}
function openOverlay(id){document.querySelector(id).classList.add('open');}function closeOverlays(){document.querySelectorAll('.overlay').forEach(e=>e.classList.remove('open'));}
document.querySelector('#begin-btn').addEventListener('click',()=>{state.started=true;document.querySelector('#intro').classList.add('hidden');toast('Find the three signal fragments. Your choices shape the awakening.');});
document.querySelector('#attack-btn').addEventListener('pointerdown',e=>{e.preventDefault();attack();});document.querySelector('#skill-btn').addEventListener('pointerdown',e=>{e.preventDefault();skill();});document.querySelector('#dodge-btn').addEventListener('pointerdown',e=>{e.preventDefault();dodge();});document.querySelector('#ult-btn').addEventListener('pointerdown',e=>{e.preventDefault();awaken();});
document.querySelector('#mobile-interact').addEventListener('pointerdown',e=>{e.preventDefault();interact();});document.querySelector('#event-action').addEventListener('click',()=>{if(!eventStarted)spawnBoss();else if(bossDefeated)toast('The rift is sealed. The frontier is yours to explore.');else{player.position.set(13,0,10);toast('You answer the call · the Titan is close.');}});
document.querySelector('#map-toggle').addEventListener('click',()=>openOverlay('#map-overlay'));document.querySelector('#menu-toggle').addEventListener('click',()=>openOverlay('#awakening-overlay'));document.querySelector('#close-awakening').addEventListener('click',closeOverlays);document.querySelectorAll('[data-close]').forEach(e=>e.addEventListener('click',closeOverlays));
document.querySelectorAll('[data-choice]').forEach(button=>button.addEventListener('click',()=>{state.choice=button.dataset.choice;if(state.choice==='save'){state.guardian=true;state.ult=Math.min(100,state.ult+35);toast('You gave up the shard. The keeper will remember.');}else{state.discoveries++;toast('You keep the shard · a new memory stirs.');}closeOverlays();refreshAwakening();document.querySelector('#objective-step').textContent='Explore the five realms and answer the Void Titan event';}));
const keyState={};addEventListener('keydown',e=>{keyState[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Space')dodge();if(e.code==='KeyE')interact();if(e.code==='Digit1')attack();if(e.code==='KeyQ')skill();if(e.code==='KeyF')awaken();if(e.code==='KeyM')openOverlay('#map-overlay');if(e.code==='Escape')closeOverlays();});addEventListener('keyup',e=>{keyState[e.code]=false;});
const stick=document.querySelector('#touch-stick'),knob=document.querySelector('#stick-knob');let stickPointer=null;stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);moveStick(e);});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)moveStick(e);});stick.addEventListener('pointerup',endStick);stick.addEventListener('pointercancel',endStick);function moveStick(e){const r=stick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=r.width*.34,len=Math.hypot(dx,dy),scale=len>max?max/len:1;state.moveX=dx*scale/max;state.moveZ=dy*scale/max;knob.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;}function endStick(e){if(e.pointerId!==stickPointer)return;stickPointer=null;state.moveX=0;state.moveZ=0;knob.style.transform='translate(0,0)';}

let lastFrame=0;
function frame(){requestAnimationFrame(frame);const dt=Math.min(.04,clock.getDelta()),t=clock.elapsedTime;
if(state.started){eventTimer-=dt;if(eventTimer<=0&&!eventStarted)spawnBoss();state.attackCd=Math.max(0,state.attackCd-dt);state.skillCd=Math.max(0,state.skillCd-dt);state.dodgeCd=Math.max(0,state.dodgeCd-dt);state.comboTimer=Math.max(0,state.comboTimer-dt);state.invuln=Math.max(0,state.invuln-dt);state.energy=Math.min(60,state.energy+dt*1.6);if(state.comboTimer===0&&state.combo){state.combo=0;document.querySelector('#combo-count').textContent='00';}
let kx=(keyState.KeyD||keyState.ArrowRight?1:0)-(keyState.KeyA||keyState.ArrowLeft?1:0),kz=(keyState.KeyS||keyState.ArrowDown?1:0)-(keyState.KeyW||keyState.ArrowUp?1:0),mx=state.moveX||kx,mz=state.moveZ||kz,len=Math.hypot(mx,mz);if(len>1){mx/=len;mz/=len;}state.walk+=dt*(len>.1?10:2);
if(state.dodge>0){state.dodge-=dt;const d=player.userData.dodgeDir||new THREE.Vector3(0,0,1);player.position.addScaledVector(d,dt*19);player.rotation.y=Math.atan2(d.x,d.z);}else if(len>.05){player.position.x+=mx*dt*7;player.position.z+=mz*dt*7;player.rotation.y=Math.atan2(mx,mz);}
player.position.x=THREE.MathUtils.clamp(player.position.x,-108,108);player.position.z=THREE.MathUtils.clamp(player.position.z,-108,108);player.position.y=0;torso.position.y=1.2+Math.sin(state.walk)*.035*(len>.05?1:0);legs.forEach((l,i)=>{l.rotation.x=len>.05?Math.sin(state.walk+i*Math.PI)*.52:0});arms.forEach((a,i)=>{a.rotation.x=len>.05?-Math.sin(state.walk+i*Math.PI)*.45:0});player.visible=state.invuln<=0||Math.floor(t*18)%2===0;
if(regionAt(player.position.x,player.position.z)==='CURSED FOREST'&&Math.random()<dt*.08&&enemies.filter(e=>e.alive&&!e.boss).length<3){const a=Math.random()*Math.PI*2;makeEnemy('CURSE HOUND',player.position.x+Math.cos(a)*12,player.position.z+Math.sin(a)*12);}
for(const e of enemies){if(!e.alive)continue;e.attack-=dt;e.exposed=Math.max(0,e.exposed-dt);e.stagger=Math.max(0,e.stagger-dt);e.hitFlash=Math.max(0,e.hitFlash-dt);const dx=player.position.x-e.root.position.x,dz=player.position.z-e.root.position.z,d=Math.hypot(dx,dz),speed=e.boss?(e.phase===3?2.4:1.35):2.15;if(d>(e.boss?4.5:1.8)&&e.stagger<=0){e.root.position.x+=dx/(d||1)*speed*dt;e.root.position.z+=dz/(d||1)*speed*dt;}e.root.rotation.y=Math.atan2(dx,dz);e.root.position.y=Math.sin(t*3+(e.boss?0:1))*.11;
if(e.boss){e.ring.rotation.z=t*.65;e.body.material=e.hitFlash>0?mat.white:e.glow;e.body.scale.y=e.phase===3?1.4:1.2;if(e.exposed>0){e.glow.emissiveIntensity=2.2+Math.sin(t*18)*.7;e.root.scale.setScalar(1+Math.sin(t*14)*.035);}else{e.glow.emissiveIntensity=1.1;e.root.scale.setScalar(1);}if(d<8&&e.attack<=0){e.attack=e.phase===3?2.1:3.3;e.stagger=.18;spawnRing(e.root.position,'#ff7398');const hitDist=d;setTimeout(()=>{if(!e.alive)return;if(hitDist<8&&player.position.distanceTo(e.root.position)<8&&state.invuln<=0){const dmg=e.phase===3?20:14;state.hp=Math.max(0,state.hp-dmg);updateVitals();toast('The Titan’s shockwave hit. Dodge the ground ring!');if(state.hp<=0){state.hp=100;player.position.set(-5,0,0);toast('The rift returned you to the crossroads.');}}else if(state.invuln>0){state.ult=Math.min(100,state.ult+12);showPrompt('PERFECT DODGE · CORE EXPOSED');e.exposed=Math.max(e.exposed,.9);}},440);}}
else{e.root.scale.setScalar(1+Math.sin(t*7)*.035);if(d<1.6&&e.attack<=0){e.attack=1.8;if(state.invuln<=0){state.hp=Math.max(0,state.hp-8);updateVitals();toast('Curse strike · dodge through its lunge.');if(state.hp<=0){state.hp=100;player.position.set(-42,0,1);toast('The city’s ward restored you.');}}else state.ult=Math.min(100,state.ult+9);}}}
if(eventStarted&&!bossDefeated)document.querySelector('#event-sub').textContent=`VOID TITAN · CORE ${Math.max(0,Math.ceil(boss.hp/boss.maxHp*100))}%${boss.exposed>0?' · EXPOSED':''}`;
const current=regionAt(player.position.x,player.position.z);if(lastRegion!==current){lastRegion=current;document.querySelector('#realm-name').textContent=current;document.querySelector('#coord-region').textContent=current;document.querySelector('#landmark-name').textContent=current;document.querySelector('#weather-name').textContent=current==='INFERNO ZONE'?'EMBERFALL':current==='FROZEN KINGDOM'?'BLUE HOUR':current==='CURSED FOREST'?'WITCHING HOUR':current==='FALLEN SHRINE'?'GOLDEN HOUR':'NIGHTFALL';}
if(t-lastFrame>.12){lastFrame=t;drawMap(miniCtx,mini.width,mini.height);refreshPrompt();document.querySelector('#coord-value').textContent=`X ${String(Math.round(player.position.x+100)).padStart(3,'0')} · Z ${String(Math.round(player.position.z+100)).padStart(3,'0')}`;updateVitals();}}
for(const o of world.children){if(o.userData.float!==undefined){o.rotation.y+=dt*.32;o.position.y+=Math.sin(t+o.userData.float)*dt*.22;}}
for(const m of markers){if(!m.userData.found){m.userData.crystal.rotation.y+=dt*.8;m.userData.crystal.position.y=1.05+Math.sin(t*2+m.position.x)*.16;m.userData.ring.rotation.z+=dt*.45;}}
for(let i=effects.length-1;i>=0;i--){const e=effects[i];e.life-=dt;if(e.kind==='particle'){e.object.position.addScaledVector(e.vel,dt);e.vel.y-=dt*3;e.object.material.transparent=true;e.object.material.opacity=Math.max(0,e.life*2);}if(e.kind==='ring'){e.object.scale.setScalar(1+(1-e.life/.55)*3);e.object.material.opacity=e.life/.55;}if(e.kind==='slash'){e.object.scale.setScalar(1+(1-e.life/.25)*1.5);e.object.material.opacity=e.life/.25;}if(e.kind==='rift'){e.object.rotation.y+=dt*4;e.object.scale.setScalar(.2+(1-e.life/.6)*2.2);if(e.object.material.opacity!==undefined)e.object.material.opacity=e.life/.6*.5;}if(e.life<=0){world.remove(e.object);effects.splice(i,1);}}
const desired=new THREE.Vector3(player.position.x,player.position.y+15.5,player.position.z+20);camera.position.lerp(desired,.075);camera.lookAt(player.position.x,player.position.y+1.1,player.position.z-1.6);renderer.render(scene,camera);}
drawMap(miniCtx,mini.width,mini.height);drawMap(bigCtx,bigMap.width,bigMap.height,true);refreshAwakening();updateVitals();frame();
addEventListener('resize',()=>{renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();});

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

// Shattered Realms: a self-contained, procedural third-person RPG prototype.
const canvas = document.querySelector('#world');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#101827');
scene.fog = new THREE.FogExp2('#101827', 0.0068);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, 0.1, 420);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.18;

scene.add(new THREE.HemisphereLight('#a9c5e8', '#161626', 2.0));
