69:   function tone(frequency, duration, type = 'sine', volume = 0.12, delay = 0, endFrequency = null) {
70:     if (!started || muted) return;
71:     const now = context.currentTime + delay;
72:     const oscillator = context.createOscillator();
73:     const gain = context.createGain();
74:     oscillator.type = type;
75:     oscillator.frequency.setValueAtTime(Math.max(30, frequency), now);
76:     if (endFrequency) oscillator.frequency.exponentialRampToValueAtTime(Math.max(30, endFrequency), now + duration);
77:     gain.gain.setValueAtTime(0.0001, now);
78:     gain.gain.exponentialRampToValueAtTime(volume, now + Math.min(0.025, duration * 0.25));
79:     gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
80:     oscillator.connect(gain);
81:     gain.connect(master);
82:     oscillator.start(now);
83:     oscillator.stop(now + duration + 0.015);
84:   }
85: 
86:   function cue(name) {
87:     if (!started || muted) return;
88:     switch (name) {
89:       case 'attack': tone(360, 0.09, 'triangle', 0.045, 0, 190); break;
90:       case 'hit': tone(115, 0.16, 'sawtooth', 0.09, 0, 54); tone(520, 0.1, 'triangle', 0.035, 0.015, 180); break;
91:       case 'dodge': tone(620, 0.22, 'sine', 0.065, 0, 220); break;
92:       case 'rift': tone(150, 0.48, 'sawtooth', 0.08, 0, 620); tone(420, 0.34, 'sine', 0.055, 0.04, 90); break;
93:       case 'pickup': tone(523.25, 0.17, 'sine', 0.07); tone(783.99, 0.25, 'sine', 0.06, 0.11); break;
94:       case 'choice': tone(392, 0.2, 'triangle', 0.07); tone(587.33, 0.32, 'sine', 0.06, 0.12); break;
95:       case 'boss': tone(92.5, 0.8, 'sawtooth', 0.11, 0, 48); tone(138.59, 0.7, 'sine', 0.08, 0.18, 55); break;
96:       case 'awakening': [261.63, 392, 523.25, 783.99].forEach((n, i) => tone(n, 0.7, 'sine', 0.055, i * 0.1)); break;
97:       case 'realm': tone(440, 0.36, 'sine', 0.055, 0, 659.25); break;
98:     }
99:   }
100: 
101:   function setMuted(value) {
102:     muted = Boolean(value);
103:     master.gain.setTargetAtTime(muted ? 0 : 0.34, context.currentTime, 0.08);
104:   }
105: 
106:   return { start, cue, setRealm, setMuted };
107: }
